package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for NumberSerializer.createContextual
 */
public class NumberSerializer_createContextual_TriageGen2Test {

    private SerializerProvider prov;
    private BeanProperty property;
    private NumberSerializer numberSerializer;

    @Before
    public void setUp() {
        prov = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        // Using BigDecimal as a common Number type for testing
        numberSerializer = new NumberSerializer(java.math.BigDecimal.class);
    }

    /**
     * Tests the case where no format override is found.
     * Should return 'this' (the current NumberSerializer instance).
     */
    @Test
    public void testCreateContextual_NoFormatOverride() throws JsonMappingException {
        // We need to mock the behavior of findFormatOverrides. 
        // Since findFormatOverrides is likely protected/internal and calls prov.findFormat(property),
        // we simulate the case where it returns null.
        when(prov.findFormat(property)).thenReturn(null);

        JsonSerializer<?> result = numberSerializer.createContextual(prov, property);

        Assert.assertSame("Should return the same instance when no format is found", numberSerializer, result);
    }

    /**
     * Tests the case where format override is STRING shape.
     * Should return ToStringSerializer.instance.
     */
    @Test
    public void testCreateContextual_StringFormatOverride() throws JsonMappingException {
        // Mock JsonFormat.Value to return STRING shape
        JsonFormat.Value mockFormatValue = mock(JsonFormat.Value.class);
        when(mockFormatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);

        // In Jackson, findFormatOverrides internally uses prov.findFormat(property)
        when(prov.findFormat(property)).thenReturn(mockFormatValue);

        JsonSerializer<?> result = numberSerializer.createContextual(prov, property);

        Assert.assertSame("Should return ToStringSerializer when shape is STRING", 
                ToStringSerializer.instance, result);
    }

    /**
     * Tests the case where format override is a different shape (e.g., NUMBER).
     * Should return 'this'.
     */
    @Test
    public void testCreateContextual_OtherFormatOverride() throws JsonMappingException {
        // Mock JsonFormat.Value to return NUMBER shape
        JsonFormat.Value mockFormatValue = mock(JsonFormat.Value.class);
        when(mockFormatValue.getShape()).thenReturn(JsonFormat.Shape.NUMBER);

        when(prov.findFormat(property)).thenReturn(mockFormatValue);

        JsonSerializer<?> result = numberSerializer.createContextual(prov, property);

        Assert.assertSame("Should return the same instance when shape is not STRING", 
                numberSerializer, result);
    }

    /**
     * Tests the case where format override is null (edge case for the switch check).
     */
    @Test
    public void testCreateContextual_NullFormat() throws JsonMappingException {
        // This is essentially covered by testCreateContextual_NoFormatOverride, 
        // but ensures the logic handles the null check explicitly.
        when(prov.findFormat(property)).thenReturn(null);

        JsonSerializer<?> result = numberSerializer.createContextual(prov, property);

        Assert.assertSame(numberSerializer, result);
    }
}
